import{_ as r,o as e,c as o,ag as a}from"./chunks/framework.QfQ7DfGu.js";const p=JSON.parse('{"title":"LA32R指令集学习指导手册","description":"","frontmatter":{"title":"LA32R指令集学习指导手册","outline":"deep"},"headers":[],"relativePath":"docs-la/others-ref.md","filePath":"docs-la/others-ref.md"}'),n={name:"docs-la/others-ref.md"};function s(l,t,i,c,d,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="la32r-指令集学习指导手册" tabindex="-1">LA32R 指令集学习指导手册 <a class="header-anchor" href="#la32r-指令集学习指导手册" aria-label="Permalink to &quot;LA32R 指令集学习指导手册&quot;">​</a></h1><p><strong>LA32R</strong>（LoongArch32 Reduced）是龙架构的 <strong>32 位精简教学向</strong> 分支：用户态整型指令约 <strong>50+ 条</strong>，可不依赖硬件浮点运行软件；含特权级、异常/中断与存储管理，在具备 TLB 时可支撑 <strong>Linux</strong>。与 <strong>LA64</strong> 设计一致、编码相通，而公开资料多围绕 LA64——本手册从软件视角说明 LA32R「为何这样设计、软硬件如何配合」，便于系统掌握该分支。</p><p class="os-interaction-read-wrap"><a href="https://la32r-study-note.readthedocs.io/zh-cn/latest/" target="_blank" rel="noopener noreferrer" class="os-interaction-read-btn">点击阅读</a></p><hr><h2 id="读者与范围" tabindex="-1">读者与范围 <a class="header-anchor" href="#读者与范围" aria-label="Permalink to &quot;读者与范围&quot;">​</a></h2><p>已了解至少一种 <strong>RISC 指令集</strong>的开发者阅读更顺；若尚无基础，建议先通过《计算机组成与设计》等建立概念。偏 <strong>CPU 硬件设计</strong>可参考《CPU 设计实战：LoongArch版》。手册<strong>不展开</strong> ELF、链接装载、GDB、Linux 公共代码等通用主题，仅作指引并推荐延伸阅读。</p><h2 id="主要内容概览" tabindex="-1">主要内容概览 <a class="header-anchor" href="#主要内容概览" aria-label="Permalink to &quot;主要内容概览&quot;">​</a></h2><ul><li><strong>用户态整型指令</strong>：机器语言与汇编、算术/逻辑/移位、访存与分支、LL/SC 与同步原语等</li><li><strong>汇编与 ABI</strong>：实验环境、汇编指示与伪指令、寄存器与调用约定、虚拟地址与栈帧、示例代码</li></ul><p>完整目录与章节正文在 Read the Docs，与顶部按钮跳转一致。</p>',9)])])}const _=r(n,[["render",s]]);export{p as __pageData,_ as default};
